mapper.select:
SELECT rb.id AS id, rb.subject AS subject, rb.content AS content, rb.created_at AS created_at, rb.hit AS hit, rb.image_url AS image_url, rb.image_size AS image_size, rb.rcp_seq AS rcp_seq,
u.id AS writer_id, u.nickname AS writer_nickname, u.profile_image_url AS writer_profile_image
FROM review_board rb LEFT OUTER JOIN users u ON rb.users_id = u.id WHERE rb.id = #{id}

mapper.update:
UPDATE review_board
SET hit = hit+1
WHERE id=#{id}

UPDATE review_board
SET subject = #{subject},
    content = #{content},
    image_url = #{image_url, jdbcType=VARCHAR}
WHERE id = #{id}
